// Vacuity probe: revert a change set's NON-test files to <base>, run the tests, expect
// red. Green means the tests do not depend on the implementation. Restores the tree.
// Cites: crabgic — "625 files / 6,216 tests stayed green" after a branch was broken.
// Usage: companion-probe.mjs <worktree> <base-ref> <test command>
import { execSync, spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const TEST_PATH = /(^|\/)(tests?|spec|__tests__)\/|(^|\/)test_[^/]+$|[._-](test|spec)\.[a-z]+$|_spec\.[a-z]+$/;

export const isTestPath = (p) => TEST_PATH.test(p);

const git = (dir, args) => execSync(`git ${args}`, { cwd: dir, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();

export function probe(dir, base, testCommand) {
  const changed = git(dir, `diff --name-only --diff-filter=AMR ${base}..HEAD`).split("\n").filter(Boolean);
  const impl = changed.filter((f) => !isTestPath(f));
  // Run 2026-09-17 magic-tower H4: nothing revertible means nothing proven — say so.
  if (impl.length === 0) return { verdict: "INAPPLICABLE", vacuous: false, reverted: [], output: "no non-test changes to revert; falsify by hand" };
  const inBase = new Set(git(dir, `ls-tree -r --name-only ${base}`).split("\n"));
  const modified = impl.filter((f) => inBase.has(f));
  const added = impl.filter((f) => !inBase.has(f));
  try {
    if (modified.length) git(dir, `checkout ${base} -- ${modified.map((f) => JSON.stringify(f)).join(" ")}`);
    if (added.length) git(dir, `rm -q -f -- ${added.map((f) => JSON.stringify(f)).join(" ")}`);
    const r = spawnSync("bash", ["-lc", testCommand], { cwd: dir, encoding: "utf8", timeout: 20 * 60 * 1000 });
    return { verdict: r.status === 0 ? "VACUOUS" : "RED", vacuous: r.status === 0, reverted: impl, output: `${r.stdout ?? ""}${r.stderr ?? ""}`.slice(-2000) };
  } finally {
    git(dir, "checkout HEAD -- .");
    git(dir, "reset -q --hard HEAD");
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const [dir, base, ...cmd] = process.argv.slice(2);
  if (!dir || !base || cmd.length === 0) {
    process.stderr.write("usage: companion-probe.mjs <worktree> <base-ref> <test command>\n");
    process.exit(64);
  }
  const r = probe(dir, base, cmd.join(" "));
  process.stdout.write(`${r.verdict}: ${r.output.split("\n")[0].slice(0, 120)} — ${r.reverted.length} implementation file(s) reverted (${r.reverted.join(", ") || "none"})\n`);
  process.exit(r.verdict === "VACUOUS" ? 1 : 0);
}

